#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
#include <queue>
using namespace std;

int main(){
vector<double> x={1,2,3,4,8},y={2,3,5,7,12};
double mx=0,my=0,xx=0,xy=0;
for(int i=0;i<int(x.size());i++){mx+=x[i]/x.size();my+=y[i]/y.size();}
for(int i=0;i<int(x.size());i++){
    xx+=pow(x[i]-mx,2);xy+=(x[i]-mx)*(y[i]-my);
}
double slope=xy/xx,intercept=my-slope*mx,orthogonal=0;
for(int i=0;i<int(x.size());i++){
    double residual=y[i]-intercept-slope*x[i];
    double leverage=1.0/x.size()+pow(x[i]-mx,2)/xx;
    orthogonal+=(x[i]-mx)*residual;
    cout<<"row "<<i<<" residual "<<residual<<" leverage "<<leverage<<"\n";
}
cout<<"slope "<<slope<<" residual orthogonality "<<orthogonal<<"\n";
return 0;
}

