int main(){
vector<double> x={-2,-1,1,2};
vector<int> y={0,0,1,1};
double intercept=0.1,slope=0.5,gradB=0,gradW=0,h00=0,h01=0,h11=0;
for(int i=0;i<int(x.size());i++){
    double p=1/(1+exp(-(intercept+slope*x[i])));
    double weight=p*(1-p);
    gradB+=p-y[i];gradW+=(p-y[i])*x[i];
    h00+=weight;h01+=weight*x[i];h11+=weight*x[i]*x[i];
}
cout<<"gradient "<<gradB<<" "<<gradW<<"\n";
cout<<"Hessian "<<h00<<" "<<h01<<" "<<h11<<"\n";
return 0;
}

