#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
#include <queue>
using namespace std;

int main(){
vector<double> x={-2,-1,1,2},y={0,0,1,1};
double intercept=0.0,slope=0,lambda=0.1,rate=0.15;
for(int step=0;step<200;step++){
    double db=0,dw=0;
    for(int i=0;i<int(x.size());i++){
        double p=1/(1+exp(-(intercept+slope*x[i])));
        db+=(p-y[i])/x.size();
        dw+=(p-y[i])*x[i]/x.size();
    }
    intercept-=rate*db;
    slope-=rate*(dw+lambda*slope);
}
cout<<"intercept "<<intercept<<" slope "<<slope<<"\n";
return 0;
}

