#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
#include <queue>
using namespace std;

int main(){
vector<double> nextReturn={0.02,-0.01,0.03,-0.02};
vector<double> baseline={1,0,1,0},candidate={1,-1,1,-1};
double fee=0.001;
auto net=[&](const vector<double>& position){
    double result=0,previous=0;
    for(int i=0;i<int(position.size());i++){
        result+=position[i]*nextReturn[i];
        result-=fee*fabs(position[i]-previous);
        previous=position[i];
    }
    return result;
};
cout<<"base "<<net(baseline)<<" candidate "<<net(candidate)<<"\n";
cout<<"incremental net value "<<net(candidate)-net(baseline)<<"\n";
return 0;
}

