vector<int> indegree(4,0);
for(const auto& outgoing:graph)for(int v:outgoing)indegree[v]++;
queue<int> ready;
for(int i=0;i<4;i++)if(indegree[i]==0)ready.push(i);
while(!ready.empty()){
    int u=ready.front();ready.pop();cout<<u<<" ";
    for(int v:graph[u]){
        indegree[v]--;
        if(indegree[v]==0)ready.push(v);
    }
}
cout<<"\n";
return 0;
}

