int main(){
vector<double> weight={0.05,0.1,0.25,0.6};
double total=0,sumSquare=0;
for(double w:weight)total+=w;
for(double& w:weight){w/=total;sumSquare+=w*w;}
double ess=1/sumSquare;
cout<<"effective sample size "<<ess<<"\n";
double firstUniform=0.1/weight.size(),accumulated=weight[0];int particle=0;
for(int k=0;k<int(weight.size());k++){
    double threshold=firstUniform+double(k)/weight.size();
    while(particle+1<int(weight.size())&&threshold>accumulated){
        particle++;accumulated+=weight[particle];
    }
    cout<<"draw "<<k<<" source particle "<<particle<<"\n";
}
return 0;
}

