#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
#include <queue>
using namespace std;

int main(){
double transition[2][2]={{0.9,0.1},{0.2,0.8}};
double likelihood[3][2]={{0.8,0.3},{0.6,0.4},{0.2,0.7}};
vector<double> posterior={0.5,0.5};
for(int t=0;t<3;t++){
    vector<double> predicted(2,0);
    for(int i=0;i<2;i++)for(int j=0;j<2;j++)
        predicted[j]+=posterior[i]*transition[i][j];
    double evidence=0;
    for(int j=0;j<2;j++){
        posterior[j]=predicted[j]*likelihood[t][j];
        evidence+=posterior[j];
    }
    for(double& p:posterior)p/=evidence;
    cout<<"time "<<t<<" state0 "<<posterior[0]<<" state1 "<<posterior[1]<<"\n";
}
return 0;
}
